use oxc_ast::ast::{JSXAttribute, JSXAttributeValue};
use oxc_span::GetSpan;
use rustc_hash::FxHashMap;

use crate::edit::{Edit, take_edited_source};

/// A class generated by the css or cx prop of an element
pub(crate) enum ClassPart {
    Literal(String),
    Expression(String),
}

/// Classes the css and cx props generate for elements with a `dynamicColor` prop, by
/// element start. They are merged into the `_sp` call instead of a `className` prop,
/// which the `_sp` spread would override
pub(crate) type DynamicColorClasses = FxHashMap<u32, Vec<ClassPart>>;

pub(super) struct SpreadSource {
    pub source: String,
    pub start: u32,
}

pub(super) struct ColorMerge<'a, 'e> {
    pub base_class: Option<&'a str>,
    pub generated_classes: &'a [ClassPart],
    pub class_attribute: Option<&'a JSXAttribute<'e>>,
    pub style_attribute: Option<&'a JSXAttribute<'e>>,
    pub spreads: &'a [SpreadSource],
}

pub(super) struct MergeOutput<'a> {
    pub source: &'a str,
    pub edits: &'a mut Vec<Edit>,
    pub needs_merge_class_names: &'a mut bool,
    pub needs_merge_styles: &'a mut bool,
}

/// The object merged by `_sp`, attributes before the last spread keep the JSX override
/// order, e.g. `<div className="a" {...props} />` uses `props.className` when it is set
pub(super) fn color_merge_object(
    merge: &ColorMerge<'_, '_>,
    output: &mut MergeOutput<'_>,
) -> Option<String> {
    let last_spread_start = merge.spreads.last().map(|spread| spread.start);
    let before_spreads = |attribute: &JSXAttribute<'_>| {
        last_spread_start.is_some_and(|start| attribute.span.start < start)
    };
    let class_value = merge
        .class_attribute
        .map(|attribute| attribute_value_source(attribute, output.source, output.edits));
    let style_value = merge
        .style_attribute
        .map(|attribute| attribute_value_source(attribute, output.source, output.edits));
    let vindur_class = VindurClass::new(merge.base_class, merge.generated_classes);

    let class_name = if !merge.spreads.is_empty()
        && merge.class_attribute.is_none_or(before_spreads)
    {
        *output.needs_merge_class_names = true;
        let class_input = merge.class_attribute.zip(class_value);
        let inputs = ordered_inputs(merge.spreads, class_input, |value| value);
        Some(format!(
            "mergeClassNames([{inputs}], {})",
            vindur_class
                .expression()
                .unwrap_or_else(|| "\"\"".to_owned())
        ))
    } else {
        let class_input = merge.class_attribute.zip(class_value);
        let literal_class =
            class_input
                .as_ref()
                .and_then(|(attribute, _)| match &attribute.value {
                    Some(JSXAttributeValue::StringLiteral(literal)) => Some(literal.value.as_str()),
                    _ => None,
                });
        match literal_class {
            Some(literal) if vindur_class.is_literal() && !vindur_class.literal.is_empty() => {
                Some(format!("\"{} {literal}\"", vindur_class.literal))
            }
            _ => {
                let mut items = vindur_class.items();
                items.extend(class_input.map(|(_, value)| value));
                join_classes(items)
            }
        }
    };
    let style = if !merge.spreads.is_empty() && merge.style_attribute.is_none_or(before_spreads) {
        *output.needs_merge_styles = true;
        let style_input = merge.style_attribute.zip(style_value);
        let inputs = ordered_inputs(merge.spreads, style_input, |value| {
            format!("{{ style: {value} }}")
        });
        Some(format!("mergeStyles([{inputs}])"))
    } else {
        style_value
    };
    if class_name.is_none() && style.is_none() {
        return None;
    }
    let mut properties = Vec::new();
    if let Some(class_name) = class_name {
        properties.push(format!("className: {class_name}"));
    }
    if let Some(style) = style {
        properties.push(format!("style: {style}"));
    }
    Some(format!("{{\n{},\n}}", properties.join(",\n")))
}

/// The spreads and an attribute before the last spread, in source order
fn ordered_inputs(
    spreads: &[SpreadSource],
    attribute: Option<(&JSXAttribute<'_>, String)>,
    format_attribute: impl Fn(String) -> String,
) -> String {
    let mut inputs = spreads
        .iter()
        .map(|spread| (spread.start, spread.source.clone()))
        .collect::<Vec<_>>();
    if let Some((attribute, value)) = attribute {
        inputs.push((attribute.span.start, format_attribute(value)));
    }
    inputs.sort_by_key(|(start, _)| *start);
    inputs
        .into_iter()
        .map(|(_, input)| input)
        .collect::<Vec<_>>()
        .join(", ")
}

struct VindurClass {
    literal: String,
    expressions: Vec<String>,
}

impl VindurClass {
    fn new(base_class: Option<&str>, generated_classes: &[ClassPart]) -> Self {
        let mut literals = base_class
            .into_iter()
            .map(str::to_owned)
            .collect::<Vec<_>>();
        let mut expressions = Vec::new();
        for part in generated_classes {
            match part {
                ClassPart::Literal(class_name) => literals.push(class_name.clone()),
                ClassPart::Expression(expression) => expressions.push(expression.clone()),
            }
        }
        Self {
            literal: literals.join(" "),
            expressions,
        }
    }

    fn is_literal(&self) -> bool {
        self.expressions.is_empty()
    }

    fn items(&self) -> Vec<String> {
        let mut items = Vec::new();
        if !self.literal.is_empty() {
            items.push(format!("\"{}\"", self.literal));
        }
        items.extend(self.expressions.iter().cloned());
        items
    }

    fn expression(&self) -> Option<String> {
        join_classes(self.items())
    }
}

fn join_classes(items: Vec<String>) -> Option<String> {
    match items.as_slice() {
        [] => None,
        [item] => Some(item.clone()),
        _ => Some(format!(
            "[{}].filter(Boolean).join(\" \")",
            items.join(", ")
        )),
    }
}

/// The value source with the edits of earlier passes inside it applied, e.g. a `css`
/// call in `className` or scoped variables in `style`
fn attribute_value_source(
    attribute: &JSXAttribute<'_>,
    source: &str,
    edits: &mut Vec<Edit>,
) -> String {
    match &attribute.value {
        Some(JSXAttributeValue::StringLiteral(value)) => format!("\"{}\"", value.value),
        Some(JSXAttributeValue::ExpressionContainer(container)) => {
            take_edited_source(source, container.expression.span(), edits)
        }
        _ => "undefined".to_owned(),
    }
}
